SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "符存审等到河中，当日渡河。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：李存审等至河中，即日济河。；核对说明：李存审复用符存审；旧书传记另将到河中系于九月，不改写主书纪时。", "status": "draft", "id": "546d27b8-d1f9-54ab-b717-b9032f6796e0", "subject_id": "f18e5602-57dc-5b6f-9cd7-3636cb8fb153", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "920年晋援同州期间；主书确月、日未载", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：李存审等至河中，即日济河。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "9540c29b-83e8-5bcf-a78b-4b588caa15d0", "subject_id": "f18e5602-57dc-5b6f-9cd7-3636cb8fb153", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记符存审：率晋援军到河中并渡河者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：李存审等至河中，即日济河。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "cc1c365b-6c42-5b52-b9c6-d180dc15d61a", "subject_id": "5cb2699c-0840-5cde-b42a-ad5f2eef0a71", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李存审：率晋援军到河中并渡河者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：李存审等至河中，即日济河。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "a13dc7ae-e28f-5188-aa13-cdcf939c3b88", "subject_id": "60ebb395-1433-501e-9e45-078c53c72fad", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《旧五代史》符存审传记九月到河中、进营朝邑。", "citation": "《旧五代史》卷五十六，段落 jiu-wudaishi-205deb4a7860-p001505；EPUB电子本，纸本及异文待核", "note": "原文：九月，次河中，進營朝邑。；核对说明：主书本段未记确月；补书记为九月，两者分别保留，不把七月遣军当作到达日期。", "status": "draft", "id": "9abdb89a-4e1a-5fd3-81a5-955a438e0bee", "subject_id": "f18e5602-57dc-5b6f-9cd7-3636cb8fb153", "source_id": "0236e2a7-65df-5075-8191-1c9d5876e92e"}, {"subject_table": "event", "field_path": "description", "claim_text": "符存审以二百精甲杂河中军逼刘鄩垒。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：梁人素轻河中兵，每战必穷追不置。存审选精甲二百，杂河中兵，直压刘鄩垒，鄩出千骑逐之；知晋人已至，大惊，自是不敢轻出。；核对说明：二百精甲与梁出千骑为主书兵数，不推造成多少伤亡。", "status": "draft", "id": "ec10715f-1e10-51e1-9914-546897095619", "subject_id": "e1d1ec82-26c1-584f-87ea-243739ebc832", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "920年晋援至河中后；确日未载", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：梁人素轻河中兵，每战必穷追不置。存审选精甲二百，杂河中兵，直压刘鄩垒，鄩出千骑逐之；知晋人已至，大惊，自是不敢轻出。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "4df95dd6-ef0e-5fec-9352-08c38240c232", "subject_id": "e1d1ec82-26c1-584f-87ea-243739ebc832", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李存审：选二百精甲杂河中兵逼梁垒者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：梁人素轻河中兵，每战必穷追不置。存审选精甲二百，杂河中兵，直压刘鄩垒，鄩出千骑逐之；知晋人已至，大惊，自是不敢轻出。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "0fc2509f-678d-5b5e-b60b-92c00723923c", "subject_id": "3144b3c3-7386-5e91-99a0-4ae53cd48519", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记刘鄩：出千骑追逐、得知晋援至后不敢轻出者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：梁人素轻河中兵，每战必穷追不置。存审选精甲二百，杂河中兵，直压刘鄩垒，鄩出千骑逐之；知晋人已至，大惊，自是不敢轻出。；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "e81d4ae7-2c72-5c82-aa4e-71f4b24f0ecb", "subject_id": "8d51da07-a3ec-5947-936c-26ce986ed6fb", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "刘鄩：出千骑追逐、得知晋援至后不敢轻出者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：梁人素轻河中兵，每战必穷追不置。存审选精甲二百，杂河中兵，直压刘鄩垒，鄩出千骑逐之；知晋人已至，大惊，自是不敢轻出。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "9ebedb0b-2e41-55a1-af08-80e99b4155a3", "subject_id": "c66998f0-ef95-5281-b056-ec97dcf5b05f", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "description", "claim_text": "晋军屯营朝邑。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：晋人军于朝邑。；核对说明：“军于”只录驻军地点，未核其现代坐标。", "status": "draft", "id": "c24f01a7-6026-59cf-975c-0a1abb140264", "subject_id": "55337854-5013-59c1-b392-def7ef3942a1", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "920年晋援同州期间；确日未载", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p014·原文件第29行", "note": "原文：晋人军于朝邑。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c8767b1f-f74b-5599-af9b-a268600760e3", "subject_id": "55337854-5013-59c1-b392-def7ef3942a1", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "description", "claim_text": "朱友谦拒诸子劝归梁，坚持晋盟。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p015·原文件第30行", "note": "原文：河中事梁久，将士皆持两端。诸军大集，刍粟踊贵，友谦诸子说友谦且归款于梁，以退其师，友谦曰：“昔晋王亲赴吾急，秉烛夜战。今方与梁相拒，又命将星行，分我资粮，岂可负邪！”；核对说明：诸子未点名，不由已录朱令德猜代发言者；“昔”援战为回顾，未另造920年旧战。", "status": "draft", "id": "1094ea13-9292-5491-a6fb-02ae6a603e26", "subject_id": "67bef158-cd26-58ce-9b72-2c2f7cf20769", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "920年同州攻援期间；确日未载", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p015·原文件第30行", "note": "原文：河中事梁久，将士皆持两端。诸军大集，刍粟踊贵，友谦诸子说友谦且归款于梁，以退其师，友谦曰：“昔晋王亲赴吾急，秉烛夜战。今方与梁相拒，又命将星行，分我资粮，岂可负邪！”；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "e68c4971-50bc-5dc5-991f-f8013e679953", "subject_id": "67bef158-cd26-58ce-9b72-2c2f7cf20769", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱友谦：拒诸子劝归梁并申说晋王旧援之恩者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p015·原文件第30行", "note": "原文：河中事梁久，将士皆持两端。诸军大集，刍粟踊贵，友谦诸子说友谦且归款于梁，以退其师，友谦曰：“昔晋王亲赴吾急，秉烛夜战。今方与梁相拒，又命将星行，分我资粮，岂可负邪！”；核对说明：与既有规范名合并；繁简或异体仅用于实体匹配，引用保留原字。", "status": "draft", "id": "1f23ff2f-bcc2-5d12-a9d9-9f4ea5d5942f", "subject_id": "bb5525ef-bfa1-507f-94d5-52e443535f7d", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱友谦：拒诸子劝归梁并申说晋王旧援之恩者。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p015·原文件第30行", "note": "原文：河中事梁久，将士皆持两端。诸军大集，刍粟踊贵，友谦诸子说友谦且归款于梁，以退其师，友谦曰：“昔晋王亲赴吾急，秉烛夜战。今方与梁相拒，又命将星行，分我资粮，岂可负邪！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "3a61387b-2179-58dc-b77e-4dafdba2703c", "subject_id": "ffd19fd0-2a18-5b6f-8d3b-a7effc2ee101", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "description", "claim_text": "晋军分兵攻华州，毁其外城。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p016·原文件第31行", "note": "原文：晋人分兵攻华州，坏其外城。；核对说明：坏外城与占领华州不同阶段；此句只证外城被毁。", "status": "draft", "id": "c4543d67-1277-5b29-9b89-3803445ce0fd", "subject_id": "32677d8c-ae89-52c5-91c3-4ff5a3e3b7ac", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "920年同州攻援期间；确日未载", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p016·原文件第31行", "note": "原文：晋人分兵攻华州，坏其外城。；核对说明：按主书本段纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b631e3e8-36f5-581e-8fdb-9ec99f3c6456", "subject_id": "32677d8c-ae89-52c5-91c3-4ff5a3e3b7ac", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb58ec0e"}, {"subject_table": "event", "field_path": "description", "claim_text": "符存审等逼梁营，刘鄩败退罗文寨。", "citation": "卷271·贞明六年（920）·zztj-v271-y0920-p016·原文件第31行", "note": "原文：李存审等按兵累旬，乃进逼刘鄩营，鄩等悉众出战，大败，收馀众退保罗文寨。；核对说明：按兵累旬是等待时长，不擅换算起止公历日。", "status": "draft", "id": "99a04288-1161-5afd-8bb8-899169115f32", "subject_id": "dad9d957-5840-5252-9800-cfddbc579260", "source_id": "0a11b510-ea25-5ae7-89a9-89f3fb